def go_rollback_drill_history_report(config: GoBackendConfig | None = None) -> dict[str, Any]:
    config = config or go_backend_config_from_env()
    history = _rollback_drill_history_summary(
        config.rollback_drill_history_path,
        max_age_days=config.rollback_drill_max_age_days,
    )
    requested = config.mode == GO_BACKEND_PROMOTED or bool(config.rollback_drill_history_path)
    checks = [
        _check(
            "go_rollback_drill_history_requested",
            requested,
            "Rollback drill history is required when CAVRA_GO_BACKEND_MODE=promoted or drill history is configured.",
            mode=config.mode,
        ),
        _check(
            "go_rollback_drill_history_file",
            history["valid"],
            history["message"],
            path=config.rollback_drill_history_path,
            history_schema=history["schema_version"],
        ),
        _check(
            "go_rollback_drill_latest_passed",
            history["latest_status"] == "pass",
            history["latest_status_message"],
            latest_drill_id=history["latest_drill_id"],
        ),
        _check(
            "go_rollback_drill_disabled_target",
            history["latest_target_mode"] == GO_BACKEND_DISABLED,
            history["target_mode_message"],
            target_mode=history["latest_target_mode"],
        ),
        _check(
            "go_rollback_drill_fallback_verified",
            history["fallback_verified"] is True,
            history["fallback_message"],
        ),
        _check(
            "go_rollback_drill_recovery_sla",
            history["recovery_sla_met"],
            history["recovery_message"],
            recovery_minutes=history["recovery_minutes"],
            max_recovery_minutes=history["max_recovery_minutes"],
        ),
        _check(
            "go_rollback_drill_freshness",
            history["fresh"],
            history["freshness_message"],
            max_age_days=config.rollback_drill_max_age_days,
            age_days=history["age_days"],
        ),
    ]
    if not requested:
        status = "not_requested"
    elif all(item["status"] == "pass" for item in checks):
        status = "ready"
    else:
        status = "needs_attention"
    return {
        "schema_version": "cavra.go-backend-pilot.rollback-drill-history.v1",
        "mode": config.mode,
        "status": status,
        "rollback_drill_history_path": config.rollback_drill_history_path,
        "rollback_drill_max_age_days": config.rollback_drill_max_age_days,
        "checks": checks,
        "history": history,
        "operator_notes": [
            "Drill history is public-safe metadata that proves promoted environments can return to Python-only mode.",
            "Record drills from operational runbooks; do not execute rollback from the browser.",
            "Keep hostnames, private endpoint scripts, secrets, and customer details out of public drill history.",
        ],
    }


def go_rollback_drill_schedule_report(config: GoBackendConfig | None = None) -> dict[str, Any]:
    config = config or go_backend_config_from_env()
    history = _rollback_drill_history_summary(
        config.rollback_drill_history_path,
        max_age_days=config.rollback_drill_max_age_days,
    )
    schedule = _rollback_drill_schedule_summary(
        config.rollback_drill_schedule_path,
        history,
        due_soon_days=config.rollback_drill_due_soon_days,
    )
    requested = config.mode == GO_BACKEND_PROMOTED or bool(config.rollback_drill_schedule_path)
    checks = [
        _check(
            "go_rollback_drill_schedule_requested",
            requested,
            "Recurring rollback drill scheduling is required when CAVRA_GO_BACKEND_MODE=promoted or a schedule is configured.",
            mode=config.mode,
        ),
        _check(
            "go_rollback_drill_schedule_file",
            schedule["valid"],
            schedule["message"],
            path=config.rollback_drill_schedule_path,
            schedule_schema=schedule["schema_version"],
        ),
        _check(
            "go_rollback_drill_schedule_active",
            schedule["active"],
            schedule["active_message"],
        ),
        _check(
            "go_rollback_drill_schedule_cadence",
            schedule["cadence_valid"],
            schedule["cadence_message"],
            interval_days=schedule["interval_days"],
        ),
        _check(
            "go_rollback_drill_schedule_next_due",
            bool(schedule["next_due_at"]),
            schedule["next_due_message"],
            next_due_at=schedule["next_due_at"],
            days_until_due=schedule["days_until_due"],
        ),
        _check(
            "go_rollback_drill_schedule_not_stale",
            not schedule["stale"],
            schedule["stale_message"],
            stale=schedule["stale"],
        ),
        _check(
            "go_rollback_drill_notification_routes",
            schedule["notification_routes_valid"],
            schedule["notification_message"],
            notification_providers=schedule["notification_providers"],
            owners=schedule["owners"],
        ),
    ]
    if not requested:
        status = "not_requested"
    elif schedule["valid"] and not schedule["stale"] and schedule["due_soon"]:
        status = "due_soon"
    elif schedule["valid"] and not schedule["stale"]:
        status = "ready"
    else:
        status = "needs_attention"
    return {
        "schema_version": "cavra.go-backend-pilot.rollback-drill-schedule.v1",
        "mode": config.mode,
        "status": status,
        "rollback_drill_schedule_path": config.rollback_drill_schedule_path,
        "rollback_drill_due_soon_days": config.rollback_drill_due_soon_days,
        "checks": checks,
        "schedule": schedule,
        "history": history,
        "operator_notes": [
            "Schedule metadata defines when promoted environments must rehearse rollback back to Python-only mode.",
            "Stale or missing schedules should notify release governance through configured connectors.",
            "Keep connector credentials in CAVRA_CONNECTOR_CONFIG or private secret stores; schedule metadata must stay public-safe.",
        ],
    }


def build_go_rollback_drill_notification_event(
    schedule_report: dict[str, Any],
    *,
    generated_by: str = "release-governance",
    routing_policy: dict[str, Any] | None = None,
    now: datetime | None = None,
) -> dict[str, Any]:
    schedule = schedule_report.get("schedule", {}) if isinstance(schedule_report.get("schedule"), dict) else {}
    history = schedule_report.get("history", {}) if isinstance(schedule_report.get("history"), dict) else {}
    routing_policy = _go_rollback_drill_effective_routing_policy(schedule, routing_policy)
    status = str(schedule_report.get("status") or "not_requested")
    alert_level = "critical" if status == "needs_attention" else "warning" if status == "due_soon" else "healthy"
    owner_routes = _go_rollback_drill_owner_routes(schedule, routing_policy, now=now)
    event = {
        "schema_version": "cavra.go-backend-pilot.rollback-drill-notification.v1",
        "product": "CAVRA",
        "event_type": "cavra.go_backend.rollback_drill.notification",
        "session_id": str(schedule.get("schedule_id") or "go-backend-rollback-drill-schedule"),
        "schedule_id": str(schedule.get("schedule_id") or ""),
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "generated_by": generated_by,
        "alert_level": alert_level,
        "status": status,
        "mode": schedule_report.get("mode", GO_BACKEND_DISABLED),
        "title": f"CAVRA Go rollback drill schedule {alert_level}",
        "summary": {
            "environment": schedule.get("environment", ""),
            "latest_drill_id": history.get("latest_drill_id", ""),
            "latest_executed_at": history.get("latest_executed_at", ""),
            "next_due_at": schedule.get("next_due_at", ""),
            "days_until_due": schedule.get("days_until_due"),
            "stale": bool(schedule.get("stale")),
            "due_soon": bool(schedule.get("due_soon")),
            "interval_days": schedule.get("interval_days"),
        },
        "owners": schedule.get("owners", []),
        "notification_providers": schedule.get("notification_providers", []),
        "owner_routes": owner_routes,
        "runbook_ref": schedule.get("runbook_ref", ""),
        "evidence_refs": history.get("evidence_refs", []),
        "controls": [
            "notification-derived-from-public-drill-schedule",
            "no-runtime-mode-change-performed-by-public-notification",
            "connector-delivery-evidence-redacts-secrets",
            "private-connectors-remain-responsible-for-ticket-or-chat-side-effects",
        ],
    }
    message = (
        f"Go backend rollback drill status is {status}; next due at "
        f"{schedule.get('next_due_at') or 'unknown'}."
    )
    event["provider_payloads"] = {
        "webhook": event | {"provider": "webhook"},
        "slack": {"text": f"{event['title']}: {message}", "metadata": event["summary"]},
        "teams": {
            "type": "message",
            "title": event["title"],
            "text": message,
            "sections": [{"facts": [{"name": key, "value": str(value)} for key, value in event["summary"].items()]}],
        },
        "jira": {
            "summary": event["title"],
            "description": json.dumps(event, indent=2, sort_keys=True),
            "labels": ["cavra", "go-backend", "rollback-drill"],
        },
        "servicenow": {
            "short_description": event["title"],
            "description": json.dumps(event, indent=2, sort_keys=True),
            "category": "software",
            "correlation_id": event["session_id"],
        },
    }
    return event


def build_go_rollback_drill_notification_plan(
    schedule_report: dict[str, Any],
    *,
    requested_provider: str = "all",
    available_providers: list[str] | None = None,
    generated_by: str = "release-governance",
    force: bool = False,
    routing_policy: dict[str, Any] | None = None,
    now: datetime | None = None,
) -> dict[str, Any]:
    now = now or datetime.now(timezone.utc)
    schedule = schedule_report.get("schedule", {}) if isinstance(schedule_report.get("schedule"), dict) else {}
    routing_policy = _go_rollback_drill_effective_routing_policy(schedule, routing_policy)
    configured = [str(item) for item in schedule.get("notification_providers", []) if isinstance(item, str)]
    available = [str(item) for item in available_providers or [] if item]
    eligible = configured or available or ["webhook"]
    requested = []
    if requested_provider != "all":
        requested = [item.strip() for item in str(requested_provider).split(",") if item.strip()]
        eligible = [item for item in eligible if item in requested]
    should_notify = force or schedule_report.get("status") in {"needs_attention", "due_soon"}
    owner_routes = _go_rollback_drill_owner_routes(
        schedule,
        routing_policy,
        eligible_providers=eligible,
        requested_providers=requested,
        now=now,
    )
    route_decisions = []
    for route in owner_routes:
        action = "deliver" if should_notify else "suppress"
        reason = "rollback drill is stale or due soon"
        if not should_notify:
            reason = "rollback drill schedule is healthy; notification suppressed"
        elif route.get("maintenance_window"):
            action = "suppress"
            reason = "matching maintenance window is active"
        elif not route.get("owner_availability", {}).get("available", True):
            action = "suppress"
            reason = str(route.get("owner_availability", {}).get("reason") or "owner calendar marks route unavailable")
        route_decisions.append(route | {"action": action, "reason": reason})
    selected = _unique_sorted(item["provider"] for item in route_decisions if item["action"] == "deliver")
    suppressed = _unique_sorted(item["provider"] for item in route_decisions if item["action"] == "suppress")
    material = json.dumps(
        {
            "schedule_id": schedule.get("schedule_id", ""),
            "status": schedule_report.get("status", ""),
            "route_decisions": route_decisions,
            "generated_by": generated_by,
        },
        sort_keys=True,
    )
    plan_id = f"gordn-{hashlib.sha256(material.encode('utf-8')).hexdigest()[:16]}"
    return {
        "schema_version": "cavra.go-backend-pilot.rollback-drill-notification-plan.v1",
        "product": "CAVRA",
        "plan_id": plan_id,
        "schedule_id": schedule.get("schedule_id", ""),
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "generated_by": generated_by,
        "status": schedule_report.get("status", "not_requested"),
        "alert_level": "critical" if schedule_report.get("status") == "needs_attention" else "warning" if schedule_report.get("status") == "due_soon" else "healthy",
        "eligible_providers": eligible,
        "selected_providers": selected,
        "acknowledgement_required_providers": selected,
        "suppressed_providers": suppressed or [provider for provider in eligible if provider not in selected],
        "owners": schedule.get("owners", []),
        "owner_routes": owner_routes,
        "route_decisions": route_decisions,
        "deliverable_route_count": len([item for item in route_decisions if item["action"] == "deliver"]),
        "suppressed_route_count": len([item for item in route_decisions if item["action"] == "suppress"]),
        "maintenance_suppressed_count": len([item for item in route_decisions if item["action"] == "suppress" and item.get("maintenance_window")]),
        "calendar_suppressed_count": len(
            [
                item
                for item in route_decisions
                if item["action"] == "suppress" and not item.get("owner_availability", {}).get("available", True)
            ]
        ),
        "next_due_at": schedule.get("next_due_at", ""),
        "reason": "rollback drill is stale or due soon" if selected else "rollback drill notification routes are suppressed",
        "controls": [
            "routing-policy-derived-from-public-safe-owner-metadata",
            "maintenance-windows-contain-no-provider-credentials",
            "owner-calendars-are-public-safe-availability-metadata",
            "notification-plan-does-not-mutate-runtime-mode",
        ],
    }


def build_go_rollback_drill_notification_plan_metadata(plan: dict[str, Any]) -> dict[str, Any]:
    return {
        "session_id": str(plan.get("plan_id") or "go-rollback-drill-notification-plan"),
        "created_at": str(plan.get("generated_at") or datetime.now(timezone.utc).isoformat()),
        "signer": str(plan.get("generated_by") or "release-governance"),
        "decision_count": len(plan.get("eligible_providers", [])),
        "blocked_count": 1 if plan.get("alert_level") == "critical" else 0,
        "approval_required_count": 1 if plan.get("alert_level") == "warning" else 0,
        "metadata_kind": "go-backend-rollback-drill-notification-plan",
        "plan_id": plan.get("plan_id"),
        "schedule_id": plan.get("schedule_id"),
        "alert_level": plan.get("alert_level"),
        "selected_providers": plan.get("selected_providers", []),
        "acknowledgement_required_providers": plan.get("acknowledgement_required_providers", []),
        "deliverable_route_count": plan.get("deliverable_route_count", 0),
        "suppressed_route_count": plan.get("suppressed_route_count", 0),
        "maintenance_suppressed_count": plan.get("maintenance_suppressed_count", 0),
        "calendar_suppressed_count": plan.get("calendar_suppressed_count", 0),
        "plan": plan,
    }


def acknowledge_go_rollback_drill_notification(
    schedule_id: str,
    *,
    provider: str,
    acknowledged_by: str,
    acknowledgement_state: str = "acknowledged",
    external_ref: str | None = None,
    notes: str | None = None,
    plan_id: str | None = None,
) -> dict[str, Any]:
    if not schedule_id:
        raise ValueError("schedule_id is required")
    if not provider:
        raise ValueError("provider is required")
    if not acknowledged_by:
        raise ValueError("acknowledged_by is required")
    state = acknowledgement_state.strip().lower().replace("-", "_")
    if state not in {"acknowledged", "dismissed", "escalated", "resolved"}:
        raise ValueError("acknowledgement_state must be acknowledged, dismissed, escalated, or resolved")
    acknowledged_at = datetime.now(timezone.utc).isoformat()
    material = json.dumps(
        {
            "schedule_id": schedule_id,
            "provider": provider,
            "acknowledged_by": acknowledged_by,
            "acknowledgement_state": state,
            "acknowledged_at": acknowledged_at,
            "plan_id": plan_id or "",
        },
        sort_keys=True,
    )
    return {
        "schema_version": "cavra.go-backend-pilot.rollback-drill-notification-ack.v1",
        "product": "CAVRA",
        "acknowledgement_id": f"gordack-{hashlib.sha256(material.encode('utf-8')).hexdigest()[:16]}",
        "schedule_id": schedule_id,
        "plan_id": plan_id or "",
        "provider": provider,
        "acknowledged_by": acknowledged_by,
        "acknowledgement_state": state,
        "acknowledged_at": acknowledged_at,
        "external_ref": external_ref or "",
        "notes": notes or "",
    }


def build_go_rollback_drill_notification_ack_metadata(acknowledgement: dict[str, Any]) -> dict[str, Any]:
    return {
        "session_id": str(acknowledgement.get("acknowledgement_id") or "go-rollback-drill-notification-ack"),
        "created_at": str(acknowledgement.get("acknowledged_at") or datetime.now(timezone.utc).isoformat()),
        "signer": str(acknowledgement.get("acknowledged_by") or "release-governance"),
        "decision_count": 1,
        "blocked_count": 0,
        "approval_required_count": 0,
        "metadata_kind": "go-backend-rollback-drill-notification-ack",
        "acknowledgement_id": acknowledgement.get("acknowledgement_id"),
        "schedule_id": acknowledgement.get("schedule_id"),
        "plan_id": acknowledgement.get("plan_id"),
        "provider": acknowledgement.get("provider"),
        "acknowledgement_state": acknowledgement.get("acknowledgement_state"),
        "acknowledgement": acknowledgement,
    }


def build_go_rollback_drill_acknowledgement_audit_package(
    items: list[dict[str, Any]],
    *,
    schedule_id: str | None = None,
    provider: str | None = None,
    owner: str | None = None,
    generated_by: str = "release-governance",
) -> dict[str, Any]:
    routes = filter_go_rollback_drill_routing_history(
        items,
        schedule_id=schedule_id,
        provider=provider,
        owner=owner,
        action="deliver",
        limit=500,
    )["items"]
    acknowledgements = filter_go_rollback_drill_notification_history(
        items,
        schedule_id=schedule_id,
        provider=provider,
        metadata_kind="go-backend-rollback-drill-notification-ack",
        limit=500,
    )["items"]
    latest_ack_by_route: dict[tuple[str, str], dict[str, Any]] = {}
    for acknowledgement in acknowledgements:
        key = (str(acknowledgement.get("schedule_id") or ""), str(acknowledgement.get("provider") or ""))
        if not key[0] or not key[1]:
            continue
        current = latest_ack_by_route.get(key)
        if current is None or str(acknowledgement.get("created_at", "")) > str(current.get("created_at", "")):
            latest_ack_by_route[key] = acknowledgement
    route_entries = []
    acknowledged_count = 0
    resolved_count = 0
    escalated_count = 0
    dismissed_count = 0
    for route in routes:
        key = (str(route.get("schedule_id") or ""), str(route.get("provider") or ""))
        ack = latest_ack_by_route.get(key)
        ack_payload = ack.get("acknowledgement") if isinstance(ack, dict) and isinstance(ack.get("acknowledgement"), dict) else ack
        state = str((ack_payload or {}).get("acknowledgement_state") or "outstanding")
        if state == "acknowledged":
            acknowledged_count += 1
        elif state == "resolved":
            resolved_count += 1
        elif state == "escalated":
            escalated_count += 1
        elif state == "dismissed":
            dismissed_count += 1
        route_entries.append(
            {
                "route_id": route.get("route_id"),
                "schedule_id": key[0],
                "plan_id": route.get("plan_id", ""),
                "provider": key[1],
                "owner": route.get("owner", "release-governance"),
                "escalation_owner": route.get("escalation_owner", route.get("owner", "release-governance")),
                "route_action": route.get("action", "deliver"),
                "route_created_at": route.get("created_at", ""),
                "acknowledgement_state": state,
                "acknowledged": state in {"acknowledged", "resolved"},
                "acknowledged_by": (ack_payload or {}).get("acknowledged_by", ""),
                "acknowledged_at": (ack_payload or {}).get("acknowledged_at", ""),
                "external_ref": (ack_payload or {}).get("external_ref", ""),
                "notes": (ack_payload or {}).get("notes", ""),
                "acknowledgement_id": (ack_payload or {}).get("acknowledgement_id", ""),
            }
        )
    outstanding_count = len([entry for entry in route_entries if not entry["acknowledged"]])
    material = json.dumps(
        {
            "generated_by": generated_by,
            "filters": {"schedule_id": schedule_id or "", "provider": provider or "", "owner": owner or ""},
            "route_entries": route_entries,
        },
        sort_keys=True,
    )
    return {
        "schema_version": "cavra.go-backend-pilot.rollback-drill-acknowledgement-audit-package.v1",
        "product": "CAVRA",
        "audit_id": f"gordackaudit-{hashlib.sha256(material.encode('utf-8')).hexdigest()[:16]}",
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "generated_by": generated_by,
        "filters": {"schedule_id": schedule_id or "", "provider": provider or "", "owner": owner or ""},
        "route_count": len(route_entries),
        "acknowledgement_count": len(acknowledgements),
        "acknowledged_count": acknowledged_count,
        "resolved_count": resolved_count,
        "escalated_count": escalated_count,
        "dismissed_count": dismissed_count,
        "outstanding_count": outstanding_count,
        "alert_level": "critical" if escalated_count or outstanding_count else "healthy",
        "routes": route_entries,
        "controls": [
            "public-safe-acknowledgement-audit-package",
            "connector-secrets-not-included",
            "latest-route-acknowledgement-state-only",
        ],
    }


def build_go_rollback_drill_acknowledgement_audit_package_metadata(package: dict[str, Any]) -> dict[str, Any]:
    return {
        "session_id": str(package.get("audit_id") or "go-rollback-drill-acknowledgement-audit-package"),
        "created_at": str(package.get("generated_at") or datetime.now(timezone.utc).isoformat()),
        "signer": str(package.get("generated_by") or "release-governance"),
        "decision_count": int(package.get("route_count") or 0),
        "blocked_count": int(package.get("outstanding_count") or 0) + int(package.get("escalated_count") or 0),
        "approval_required_count": int(package.get("outstanding_count") or 0),
        "metadata_kind": "go-backend-rollback-drill-acknowledgement-audit-package",
        "audit_id": package.get("audit_id"),
        "alert_level": package.get("alert_level"),
        "route_count": package.get("route_count", 0),
        "acknowledgement_count": package.get("acknowledgement_count", 0),
        "outstanding_count": package.get("outstanding_count", 0),
        "acknowledgement_audit_package": package,
    }


def build_go_rollback_drill_acknowledgement_audit_delivery_plan(
    package: dict[str, Any],
    *,
    requested_provider: str = "all",
    available_providers: list[str] | None = None,
    generated_by: str = "release-governance",
    cadence: str = "on_demand",
    schedule_ref: str | None = None,
    next_delivery_at: str | None = None,
) -> dict[str, Any]:
    available = [str(item) for item in available_providers or [] if item]
    eligible = available or ["webhook"]
    requested = []
    if requested_provider != "all":
        requested = [item.strip() for item in str(requested_provider).split(",") if item.strip()]
        eligible = [item for item in eligible if item in requested]
    material = json.dumps(
        {
            "audit_id": package.get("audit_id", ""),
            "eligible": eligible,
            "generated_by": generated_by,
            "cadence": cadence,
            "schedule_ref": schedule_ref or "",
            "next_delivery_at": next_delivery_at or "",
        },
        sort_keys=True,
    )
    delivery_id = f"gordackdelivery-{hashlib.sha256(material.encode('utf-8')).hexdigest()[:16]}"
    return {
        "schema_version": "cavra.go-backend-pilot.rollback-drill-acknowledgement-audit-delivery-plan.v1",
        "product": "CAVRA",
        "delivery_id": delivery_id,
        "audit_id": package.get("audit_id", ""),
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "generated_by": generated_by,
        "cadence": cadence or "on_demand",
        "schedule_ref": schedule_ref or "",
        "next_delivery_at": next_delivery_at or "",
        "requested_provider": requested_provider,
        "requested_providers": requested,
        "selected_providers": eligible,
        "destination_count": len(eligible),
        "route_count": int(package.get("route_count") or 0),
        "outstanding_count": int(package.get("outstanding_count") or 0),
        "escalated_count": int(package.get("escalated_count") or 0),
        "alert_level": package.get("alert_level", "healthy"),
        "filters": package.get("filters", {}),
        "controls": [
            "acknowledgement-audit-delivery-uses-public-safe-package",
            "connector-secrets-not-included-in-delivery-plan",
            "scheduled-delivery-is-metadata-only-in-community-edition",
        ],
    }


def _go_rollback_drill_ack_audit_route_delivery_rows(package: dict[str, Any]) -> list[dict[str, Any]]:
    routes = package.get("routes", []) if isinstance(package.get("routes"), list) else []
    return [
        {
            "route_id": route.get("route_id", ""),
            "schedule_id": route.get("schedule_id", ""),
            "plan_id": route.get("plan_id", ""),
            "provider": route.get("provider", ""),
            "owner": route.get("owner", ""),
            "escalation_owner": route.get("escalation_owner", ""),
            "acknowledgement_state": route.get("acknowledgement_state", "outstanding"),
            "acknowledged": bool(route.get("acknowledged")),
            "acknowledged_by": route.get("acknowledged_by", ""),
            "acknowledged_at": route.get("acknowledged_at", ""),
            "external_ref": route.get("external_ref", ""),
            "acknowledgement_id": route.get("acknowledgement_id", ""),
        }
        for route in routes
        if isinstance(route, dict)
    ]


def build_go_rollback_drill_acknowledgement_audit_delivery_event(
    package: dict[str, Any],
    plan: dict[str, Any],
    *,
    generated_by: str = "release-governance",
) -> dict[str, Any]:
    routes = _go_rollback_drill_ack_audit_route_delivery_rows(package)
    summary = {
        "audit_id": package.get("audit_id", ""),
        "delivery_id": plan.get("delivery_id", ""),
        "route_count": package.get("route_count", 0),
        "acknowledged_count": package.get("acknowledged_count", 0),
        "resolved_count": package.get("resolved_count", 0),
        "escalated_count": package.get("escalated_count", 0),
        "dismissed_count": package.get("dismissed_count", 0),
        "outstanding_count": package.get("outstanding_count", 0),
        "alert_level": package.get("alert_level", "healthy"),
        "filters": package.get("filters", {}),
        "cadence": plan.get("cadence", "on_demand"),
        "schedule_ref": plan.get("schedule_ref", ""),
        "next_delivery_at": plan.get("next_delivery_at", ""),
    }
    title = f"CAVRA rollback drill acknowledgement audit {summary['alert_level']}"
    description = (
        f"Audit package {summary['audit_id']} has {summary['outstanding_count']} outstanding "
        f"route(s) and {summary['escalated_count']} escalated route(s)."
    )
    event = {
        "schema_version": "cavra.go-backend-pilot.rollback-drill-acknowledgement-audit-delivery.v1",
        "product": "CAVRA",
        "event_type": "cavra.go_backend.rollback_drill.acknowledgement_audit_delivery",
        "session_id": str(plan.get("delivery_id") or package.get("audit_id") or "go-rollback-drill-ack-audit-delivery"),
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "generated_by": generated_by,
        "title": title,
        "alert_level": summary["alert_level"],
        "blocked_count": int(package.get("outstanding_count") or 0) + int(package.get("escalated_count") or 0),
        "max_severity": "high" if summary["alert_level"] == "critical" else "low",
        "audit_package_summary": summary,
        "delivery_plan": plan,
        "routes": routes,
        "controls": [
            "delivery-event-redacts-connector-secrets",
            "route-notes-are-not-sent-to-connectors",
            "siem-itsm-routing-uses-public-safe-acknowledgement-state",
        ],
    }
    event["provider_payloads"] = {
        "webhook": event | {"provider": "webhook"},
        "splunk": {"event": event | {"provider": "splunk"}, "sourcetype": "cavra:rollback_drill_ack_audit"},
        "sentinel": {"records": [event | {"provider": "sentinel"}]},
        "datadog": {"events": [event | {"provider": "datadog"}]},
        "slack": {
            "text": f"{title}: {description}",
            "metadata": summary,
        },
        "teams": {
            "type": "message",
            "title": title,
            "text": description,
            "sections": [{"facts": [{"name": key, "value": str(value)} for key, value in summary.items()]}],
        },
        "jira": {
            "summary": title,
            "description": json.dumps(event, indent=2, sort_keys=True),
            "labels": ["cavra", "go-backend", "rollback-drill", "acknowledgement-audit"],
        },
        "servicenow": {
            "short_description": title,
            "description": json.dumps(event, indent=2, sort_keys=True),
            "category": "software",
            "correlation_id": event["session_id"],
        },
    }
    return event


