def _go_retry_execution_key(item: dict[str, Any]) -> tuple[str, str, str, str]:
    return (
        "",
        str(item.get("provider") or ""),
        str(item.get("delivery_id") or ""),
        str(item.get("audit_id") or ""),
    )


def _approved_go_retry_execution_keys(items: list[dict[str, Any]]) -> set[tuple[str, str, str, str]]:
    approved = set()
    for item in filter_go_rollback_drill_notification_history(items, limit=500)["items"]:
        if (
            item.get("metadata_kind")
            == "go-backend-rollback-drill-acknowledgement-audit-delivery-retry-execution-approval-decision"
            and item.get("approval_state") == "approved"
        ):
            approved.add(_go_retry_execution_key(item))
    return approved


def build_go_rollback_drill_acknowledgement_audit_delivery_retry_execution_approval_plan(
    items: list[dict[str, Any]],
    *,
    generated_by: str = "release-governance",
    policy: dict[str, Any] | None = None,
    now: datetime | None = None,
) -> dict[str, Any]:
    now = now or datetime.now(timezone.utc)
    policy = policy or {}
    require_retry_ack = bool(policy.get("require_retry_ack", True))
    history = filter_go_rollback_drill_notification_history(items, limit=500)["items"]
    retry_plans = [
        item
        for item in history
        if item.get("metadata_kind") == "go-backend-rollback-drill-acknowledgement-audit-delivery-retry-plan"
    ]
    retry_acks = [
        item
        for item in history
        if item.get("metadata_kind") == "go-backend-rollback-drill-acknowledgement-audit-delivery-retry-ack"
        and item.get("acknowledgement_state") in {"accepted", "resolved"}
    ]
    acked_keys = {_go_retry_execution_key(item) for item in retry_acks}
    approved_keys = _approved_go_retry_execution_keys(items)
    approval_decisions: list[dict[str, Any]] = []
    seen_keys: set[tuple[str, str, str, str]] = set()
    for metadata in retry_plans:
        plan = metadata.get("acknowledgement_audit_delivery_retry_plan")
        if not isinstance(plan, dict):
            plan = metadata
        retry_plan_id = str(plan.get("retry_plan_id") or metadata.get("retry_plan_id") or "")
        for decision in plan.get("retry_decisions", []):
            if not isinstance(decision, dict) or decision.get("action") not in {"retry", "wait"}:
                continue
            candidate = {
                "retry_plan_id": retry_plan_id,
                "provider": str(decision.get("provider") or ""),
                "delivery_id": str(decision.get("delivery_id") or ""),
                "audit_id": str(decision.get("audit_id") or ""),
            }
            key = _go_retry_execution_key(candidate)
            if key in seen_keys:
                continue
            seen_keys.add(key)
            if key in approved_keys:
                action = "already_approved"
                reason = "retry execution already has approved execution evidence"
                approval_required = False
            elif require_retry_ack and key not in acked_keys:
                action = "wait_for_retry_ack"
                reason = "retry execution requires accepted retry acknowledgement before approval"
                approval_required = False
            else:
                action = "request_approval"
                reason = "retry execution is acknowledged and ready for governed approval"
                approval_required = True
            approval_decisions.append(
                {
                    **candidate,
                    "action": action,
                    "reason": reason,
                    "approval_required": approval_required,
                    "retry_count": decision.get("retry_count", 0),
                    "next_retry_at": decision.get("next_retry_at"),
                    "failed_status_codes": decision.get("failed_status_codes", []),
                    "retry_action": decision.get("action"),
                }
            )
    approval_required_count = len([item for item in approval_decisions if item["approval_required"]])
    approved_count = len([item for item in approval_decisions if item["action"] == "already_approved"])
    waiting_count = len([item for item in approval_decisions if item["action"] in {"wait_for_retry_ack", "wait_for_retry_window"}])
    generated_at = now.isoformat()
    material = json.dumps(
        {"generated_at": generated_at, "approval_decisions": approval_decisions},
        sort_keys=True,
    )
    approval_plan_id = f"gordackretryapproval-{hashlib.sha256(material.encode('utf-8')).hexdigest()[:16]}"
    return {
        "schema_version": "cavra.go-backend-pilot.rollback-drill-acknowledgement-audit-delivery-retry-execution-approval-plan.v1",
        "product": "CAVRA",
        "approval_plan_id": approval_plan_id,
        "generated_at": generated_at,
        "generated_by": generated_by,
        "alert_level": "critical" if approval_required_count else "warning" if waiting_count else "healthy",
        "decision_count": len(approval_decisions),
        "approval_required_count": approval_required_count,
        "approved_count": approved_count,
        "waiting_count": waiting_count,
        "require_retry_ack": require_retry_ack,
        "approval_decisions": approval_decisions,
        "controls": [
            "retry-execution-approval-derived-from-public-retry-metadata",
            "retry-execution-requires-explicit-approval-before-live-worker-delivery",
            "approval-plan-contains-no-provider-credentials",
            "private-connectors-remain-responsible-for-side-effects",
        ],
    }


def build_go_rollback_drill_acknowledgement_audit_delivery_retry_execution_approval_plan_metadata(
    plan: dict[str, Any],
) -> dict[str, Any]:
    return {
        "session_id": plan.get("approval_plan_id"),
        "created_at": plan.get("generated_at"),
        "signer": plan.get("generated_by", "release-governance"),
        "decision_count": int(plan.get("decision_count") or 0),
        "blocked_count": int(plan.get("waiting_count") or 0),
        "approval_required_count": int(plan.get("approval_required_count") or 0),
        "metadata_kind": "go-backend-rollback-drill-acknowledgement-audit-delivery-retry-execution-approval-plan",
        "approval_plan_id": plan.get("approval_plan_id"),
        "alert_level": plan.get("alert_level"),
        "approved_count": plan.get("approved_count", 0),
        "waiting_count": plan.get("waiting_count", 0),
        "retry_execution_approval_plan": plan,
    }


def decide_go_rollback_drill_acknowledgement_audit_delivery_retry_execution_approval(
    approval_plan_id: str,
    *,
    provider: str,
    decided_by: str,
    approval_state: str = "approved",
    retry_plan_id: str | None = None,
    delivery_id: str | None = None,
    audit_id: str | None = None,
    external_ref: str | None = None,
    notes: str | None = None,
    now: datetime | None = None,
) -> dict[str, Any]:
    if not approval_plan_id:
        raise ValueError("approval_plan_id is required")
    provider = str(provider or "").strip().lower().replace("-", "_")
    if not provider:
        raise ValueError("provider is required")
    if not decided_by:
        raise ValueError("decided_by is required")
    state = approval_state.strip().lower().replace("-", "_")
    if state not in {"approved", "denied", "deferred", "expired"}:
        raise ValueError("approval_state must be approved, denied, deferred, or expired")
    now = now or datetime.now(timezone.utc)
    decided_at = now.isoformat()
    material = f"{approval_plan_id}|{retry_plan_id or ''}|{provider}|{delivery_id or ''}|{state}|{decided_by}|{decided_at}"
    decision_id = f"gordackretryapprovaldecision-{hashlib.sha256(material.encode('utf-8')).hexdigest()[:16]}"
    return {
        "schema_version": "cavra.go-backend-pilot.rollback-drill-acknowledgement-audit-delivery-retry-execution-approval-decision.v1",
        "product": "CAVRA",
        "decision_id": decision_id,
        "approval_plan_id": approval_plan_id,
        "retry_plan_id": retry_plan_id or "",
        "delivery_id": delivery_id or "",
        "audit_id": audit_id or "",
        "provider": provider,
        "approval_state": state,
        "decided_by": decided_by,
        "decided_at": decided_at,
        "external_ref": external_ref or "",
        "notes": notes or "",
        "controls": [
            "retry-execution-approval-decision-records-governed-operator-intent",
            "approval-decision-contains-no-provider-token-or-secret",
            "live-retry-worker-execution-must-reference-approved-decision",
        ],
    }


def build_go_rollback_drill_acknowledgement_audit_delivery_retry_execution_approval_decision_metadata(
    decision: dict[str, Any],
) -> dict[str, Any]:
    return {
        "session_id": decision.get("decision_id"),
        "created_at": decision.get("decided_at"),
        "signer": decision.get("decided_by", "release-governance"),
        "decision_count": 1,
        "blocked_count": 0 if decision.get("approval_state") == "approved" else 1,
        "approval_required_count": 0,
        "metadata_kind": "go-backend-rollback-drill-acknowledgement-audit-delivery-retry-execution-approval-decision",
        "decision_id": decision.get("decision_id"),
        "approval_plan_id": decision.get("approval_plan_id"),
        "retry_plan_id": decision.get("retry_plan_id"),
        "delivery_id": decision.get("delivery_id"),
        "audit_id": decision.get("audit_id"),
        "provider": decision.get("provider"),
        "approval_state": decision.get("approval_state"),
        "external_ref": decision.get("external_ref"),
        "retry_execution_approval_decision": decision,
    }


def _go_retry_execution_approval_by_key(items: list[dict[str, Any]]) -> dict[tuple[str, str, str, str], dict[str, Any]]:
    approvals = {}
    for item in filter_go_rollback_drill_notification_history(items, limit=500)["items"]:
        if (
            item.get("metadata_kind")
            == "go-backend-rollback-drill-acknowledgement-audit-delivery-retry-execution-approval-decision"
            and item.get("approval_state") == "approved"
        ):
            decision = (
                item.get("retry_execution_approval_decision")
                if isinstance(item.get("retry_execution_approval_decision"), dict)
                else item
            )
            approvals[_go_retry_execution_key(item)] = decision
    return approvals


def build_go_rollback_drill_acknowledgement_audit_delivery_retry_execution_record(
    run: dict[str, Any],
    retry_decision: dict[str, Any],
    *,
    approval_decision: dict[str, Any],
    delivery_plan: dict[str, Any] | None = None,
    delivery: dict[str, Any] | None = None,
    delivery_metadata: dict[str, Any] | None = None,
    skipped: str | None = None,
    executed_by: str = "release-governance",
    now: datetime | None = None,
) -> dict[str, Any]:
    if run.get("dry_run", True):
        raise ValueError("live retry execution records require a non-dry-run worker run")
    if not approval_decision or approval_decision.get("approval_state") != "approved":
        raise ValueError("live retry execution records require an approved retry execution decision")
    provider = str(retry_decision.get("provider") or approval_decision.get("provider") or "").strip().lower().replace("-", "_")
    if not provider:
        raise ValueError("provider is required")
    retry_plan_id = str(
        retry_decision.get("retry_plan_id")
        or approval_decision.get("retry_plan_id")
        or (run.get("retry_plan", {}) if isinstance(run.get("retry_plan"), dict) else {}).get("retry_plan_id")
        or ""
    )
    delivery_id = str(retry_decision.get("delivery_id") or approval_decision.get("delivery_id") or "")
    audit_id = str(retry_decision.get("audit_id") or approval_decision.get("audit_id") or "")
    run_id = str(run.get("run_id") or "")
    if not run_id:
        raise ValueError("run_id is required")
    now = now or datetime.now(timezone.utc)
    executed_at = now.isoformat()
    delivery_success = bool(delivery_metadata.get("delivery_success")) if isinstance(delivery_metadata, dict) else bool(delivery and delivery.get("success"))
    if skipped:
        execution_status = "skipped"
    elif delivery_success:
        execution_status = "delivered"
    else:
        execution_status = "failed"
    material = {
        "run_id": run_id,
        "retry_plan_id": retry_plan_id,
        "provider": provider,
        "delivery_id": delivery_id,
        "audit_id": audit_id,
        "approval_decision_id": approval_decision.get("decision_id", ""),
        "delivery_metadata_id": delivery_metadata.get("session_id", "") if isinstance(delivery_metadata, dict) else "",
        "execution_status": execution_status,
        "executed_at": executed_at,
    }
    execution_hash = hashlib.sha256(json.dumps(material, sort_keys=True).encode("utf-8")).hexdigest()
    execution_id = f"gordackretryexec-{execution_hash[:16]}"
    return {
        "schema_version": "cavra.go-backend-pilot.rollback-drill-acknowledgement-audit-delivery-retry-execution-record.v1",
        "product": "CAVRA",
        "execution_id": execution_id,
        "execution_hash": execution_hash,
        "execution_status": execution_status,
        "executed_at": executed_at,
        "executed_by": executed_by,
        "run_id": run_id,
        "retry_plan_id": retry_plan_id,
        "approval_decision_id": approval_decision.get("decision_id", ""),
        "approval_plan_id": approval_decision.get("approval_plan_id", ""),
        "delivery_id": delivery_id,
        "audit_id": audit_id,
        "provider": provider,
        "skipped": skipped or "",
        "delivery_plan_id": delivery_plan.get("delivery_id", "") if isinstance(delivery_plan, dict) else "",
        "delivery_metadata_id": delivery_metadata.get("session_id", "") if isinstance(delivery_metadata, dict) else "",
        "delivery_success": delivery_success,
        "selected_providers": delivery_plan.get("selected_providers", []) if isinstance(delivery_plan, dict) else [],
        "public_evidence_refs": [
            ref
            for ref in [
                f"go-rollback-drill-retry-worker://{run_id}",
                f"go-rollback-drill-retry-approval://{approval_decision.get('decision_id', '')}",
                f"go-rollback-drill-audit-delivery://{delivery_plan.get('delivery_id', '')}"
                if isinstance(delivery_plan, dict)
                else "",
                f"connector-delivery://{delivery_metadata.get('session_id', '')}"
                if isinstance(delivery_metadata, dict)
                else "",
            ]
            if ref and not ref.endswith("://")
        ],
        "controls": [
            "live-retry-execution-record-bound-to-approved-decision",
            "execution-record-derived-from-public-safe-worker-and-delivery-metadata",
            "execution-hash-covers-worker-approval-delivery-and-status",
            "record-contains-no-connector-secret-or-private-endpoint",
        ],
    }


def build_go_rollback_drill_acknowledgement_audit_delivery_retry_execution_record_metadata(
    record: dict[str, Any],
) -> dict[str, Any]:
    return {
        "session_id": record.get("execution_id"),
        "created_at": record.get("executed_at"),
        "signer": record.get("executed_by", "release-governance"),
        "decision_count": 1,
        "blocked_count": 0 if record.get("execution_status") == "delivered" else 1,
        "approval_required_count": 0,
        "metadata_kind": "go-backend-rollback-drill-acknowledgement-audit-delivery-retry-execution-record",
        "execution_id": record.get("execution_id"),
        "execution_hash": record.get("execution_hash"),
        "execution_status": record.get("execution_status"),
        "run_id": record.get("run_id"),
        "retry_plan_id": record.get("retry_plan_id"),
        "approval_decision_id": record.get("approval_decision_id"),
        "delivery_id": record.get("delivery_id"),
        "audit_id": record.get("audit_id"),
        "provider": record.get("provider"),
        "delivery_success": record.get("delivery_success"),
        "retry_execution_record": record,
    }


def _go_connector_recovery_category(provider: str) -> str:
    normalized = provider.strip().lower().replace("-", "_")
    if normalized in {"splunk", "sentinel", "datadog"}:
        return "siem"
    if normalized in {"jira", "servicenow"}:
        return "itsm"
    if normalized in {"slack", "teams", "pagerduty", "email"}:
        return "chatops"
    return "webhook"


def build_go_rollback_drill_acknowledgement_audit_delivery_connector_recovery_playbook(
    items: list[dict[str, Any]],
    *,
    generated_by: str = "release-governance",
    min_failure_count: int = 2,
    lookback_hours: int = 24,
    now: datetime | None = None,
) -> dict[str, Any]:
    now = now or datetime.now(timezone.utc)
    min_failure_count = max(1, int(min_failure_count or 2))
    lookback_hours = max(1, int(lookback_hours or 24))
    cutoff = now - timedelta(hours=lookback_hours)
    history = filter_go_rollback_drill_notification_history(items, limit=500)["items"]
    failures = []
    for item in history:
        if item.get("metadata_kind") != "release-connector-delivery" or item.get("delivery_success"):
            continue
        if item.get("connector_delivery_source") not in {
            "go_backend_rollback_drill_acknowledgement_audit",
            "go_backend_rollback_drill_acknowledgement_audit_worker_health_alert",
        }:
            continue
        created_at = _parse_iso_datetime(str(item.get("created_at") or ""))
        if created_at is not None and created_at < cutoff:
            continue
        providers = [str(provider) for provider in item.get("failed_providers", []) if provider]
        if not providers:
            providers = [str(provider) for provider in item.get("providers", []) if provider]
        for provider in providers:
            failures.append({"provider": provider.strip().lower().replace("-", "_"), "item": item})
    grouped: dict[str, list[dict[str, Any]]] = {}
    for failure in failures:
        grouped.setdefault(failure["provider"], []).append(failure["item"])
    provider_playbooks = []
    for provider, provider_failures in sorted(grouped.items()):
        if len(provider_failures) < min_failure_count:
            continue
        category = _go_connector_recovery_category(provider)
        provider_playbooks.append(
            {
                "provider": provider,
                "category": category,
                "failure_count": len(provider_failures),
                "latest_failure_at": max(str(item.get("created_at") or "") for item in provider_failures),
                "status_codes": _unique_sorted(
                    str(code)
                    for item in provider_failures
                    for code in item.get("status_codes", [])
                    if code is not None
                ),
                "recovery_steps": [
                    "confirm connector destination ownership and maintenance status",
                    "verify outbound network path and endpoint allowlist",
                    "rotate or reissue connector credential in private secret manager if authentication failed",
                    "run acknowledgement audit delivery worker in dry-run mode",
                    "request retry execution approval before live retry delivery",
                    "record external incident or change reference after recovery",
                ],
                "private_connector_boundary": (
                    "Community Edition records the public-safe recovery playbook only; connector credential "
                    "rotation and ticket/chat side effects remain private connector or operator runbook work."
                ),
            }
        )
    generated_at = now.isoformat()
    material = json.dumps(
        {"generated_at": generated_at, "provider_playbooks": provider_playbooks},
        sort_keys=True,
    )
    playbook_id = f"gordackrecovery-{hashlib.sha256(material.encode('utf-8')).hexdigest()[:16]}"
    return {
        "schema_version": "cavra.go-backend-pilot.rollback-drill-acknowledgement-audit-delivery-connector-recovery-playbook.v1",
        "product": "CAVRA",
        "playbook_id": playbook_id,
        "generated_at": generated_at,
        "generated_by": generated_by,
        "alert_level": "critical" if provider_playbooks else "healthy",
        "lookback_hours": lookback_hours,
        "min_failure_count": min_failure_count,
        "provider_count": len(provider_playbooks),
        "failure_count": sum(item["failure_count"] for item in provider_playbooks),
        "provider_playbooks": provider_playbooks,
        "controls": [
            "connector-recovery-playbook-derived-from-redacted-delivery-metadata",
            "playbook-contains-no-connector-secrets",
            "credential-rotation-remains-private-operator-or-enterprise-connector-responsibility",
            "live-retry-delivery-remains-approval-bound",
        ],
    }


def build_go_rollback_drill_acknowledgement_audit_delivery_connector_recovery_playbook_metadata(
    playbook: dict[str, Any],
) -> dict[str, Any]:
    return {
        "session_id": playbook.get("playbook_id"),
        "created_at": playbook.get("generated_at"),
        "signer": playbook.get("generated_by", "release-governance"),
        "decision_count": int(playbook.get("provider_count") or 0),
        "blocked_count": int(playbook.get("failure_count") or 0),
        "approval_required_count": int(playbook.get("provider_count") or 0),
        "metadata_kind": "go-backend-rollback-drill-acknowledgement-audit-delivery-connector-recovery-playbook",
        "playbook_id": playbook.get("playbook_id"),
        "alert_level": playbook.get("alert_level"),
        "provider_count": playbook.get("provider_count", 0),
        "failure_count": playbook.get("failure_count", 0),
        "connector_recovery_playbook": playbook,
    }


def close_go_rollback_drill_acknowledgement_audit_delivery_connector_recovery(
    playbook_id: str,
    *,
    provider: str,
    closed_by: str,
    closure_state: str = "resolved",
    external_ref: str | None = None,
    notes: str | None = None,
    verification_refs: list[str] | None = None,
    now: datetime | None = None,
) -> dict[str, Any]:
    if not playbook_id:
        raise ValueError("playbook_id is required")
    provider = str(provider or "").strip().lower().replace("-", "_")
    if not provider:
        raise ValueError("provider is required")
    if not closed_by:
        raise ValueError("closed_by is required")
    state = closure_state.strip().lower().replace("-", "_")
    if state not in {"resolved", "mitigated", "deferred", "escalated", "reopened"}:
        raise ValueError("closure_state must be resolved, mitigated, deferred, escalated, or reopened")
    now = now or datetime.now(timezone.utc)
    closed_at = now.isoformat()
    verification_refs = [str(ref) for ref in verification_refs or [] if ref]
    material = {
        "playbook_id": playbook_id,
        "provider": provider,
        "closure_state": state,
        "closed_by": closed_by,
        "closed_at": closed_at,
        "external_ref": external_ref or "",
        "verification_refs": verification_refs,
    }
    closure_hash = hashlib.sha256(json.dumps(material, sort_keys=True).encode("utf-8")).hexdigest()
    closure_id = f"gordackrecoveryclosure-{closure_hash[:16]}"
    return {
        "schema_version": "cavra.go-backend-pilot.rollback-drill-acknowledgement-audit-delivery-connector-recovery-closure.v1",
        "product": "CAVRA",
        "closure_id": closure_id,
        "closure_hash": closure_hash,
        "playbook_id": playbook_id,
        "provider": provider,
        "closure_state": state,
        "closed_by": closed_by,
        "closed_at": closed_at,
        "external_ref": external_ref or "",
        "notes": notes or "",
        "verification_refs": verification_refs,
        "controls": [
            "connector-recovery-closure-records-public-safe-operator-evidence",
            "closure-hash-covers-playbook-provider-state-and-verification-refs",
            "closure-record-contains-no-connector-secret-or-private-endpoint",
            "private-ticket-chat-and-credential-side-effects-remain-outside-public-repo",
        ],
    }


def build_go_rollback_drill_acknowledgement_audit_delivery_connector_recovery_closure_metadata(
    closure: dict[str, Any],
) -> dict[str, Any]:
    return {
        "session_id": closure.get("closure_id"),
        "created_at": closure.get("closed_at"),
        "signer": closure.get("closed_by", "release-governance"),
        "decision_count": 1,
        "blocked_count": 0 if closure.get("closure_state") in {"resolved", "mitigated"} else 1,
        "approval_required_count": 0,
        "metadata_kind": "go-backend-rollback-drill-acknowledgement-audit-delivery-connector-recovery-closure",
        "closure_id": closure.get("closure_id"),
        "closure_hash": closure.get("closure_hash"),
        "playbook_id": closure.get("playbook_id"),
        "provider": closure.get("provider"),
        "closure_state": closure.get("closure_state"),
        "external_ref": closure.get("external_ref"),
        "connector_recovery_closure": closure,
    }


def filter_go_rollback_drill_acknowledgement_audit_delivery_worker_health_alert_history(
    items: list[dict[str, Any]],
    *,
    health_id: str | None = None,
    provider: str | None = None,
    metadata_kind: str | None = None,
    acknowledgement_state: str | None = None,
    suppressed: bool | None = None,
    limit: int = 50,
    offset: int = 0,
) -> dict[str, Any]:
    filtered = [
        item
        for item in filter_go_rollback_drill_notification_history(items, limit=500)["items"]
        if item.get("metadata_kind")
        in {
            "go-backend-rollback-drill-acknowledgement-audit-delivery-worker-health-alert-plan",
            "go-backend-rollback-drill-acknowledgement-audit-delivery-worker-health-alert-ack",
            "release-connector-delivery",
        }
        and (
            item.get("metadata_kind") != "release-connector-delivery"
            or item.get("connector_delivery_source")
            == "go_backend_rollback_drill_acknowledgement_audit_worker_health_alert"
        )
    ]
    if health_id:
        filtered = [
            item
            for item in filtered
            if item.get("health_id") == health_id or item.get("event_id") == health_id or item.get("session_id") == health_id
        ]
    if provider:
        provider_key = provider.strip().lower().replace("-", "_")
        filtered = [
            item
            for item in filtered
            if item.get("provider") == provider_key
            or provider_key in {str(value) for value in item.get("providers", [])}
            or provider_key in {str(value) for value in item.get("selected_providers", [])}
            or provider_key in {str(value) for value in item.get("suppressed_providers", [])}
        ]
    if metadata_kind:
        filtered = [item for item in filtered if item.get("metadata_kind") == metadata_kind]
    if acknowledgement_state:
        state = acknowledgement_state.strip().lower().replace("-", "_")
        filtered = [item for item in filtered if item.get("acknowledgement_state") == state]
    if suppressed is not None:
        filtered = [item for item in filtered if (len(item.get("suppressed_providers", [])) > 0) is suppressed]
    filtered = sorted(filtered, key=lambda item: str(item.get("created_at", "")), reverse=True)
    return {
        "schema_version": "cavra.go-backend-pilot.rollback-drill-acknowledgement-audit-delivery-worker-health-alert-history.v1",
        "product": "CAVRA",
        "items": filtered[offset : offset + limit],
        "total": len(filtered),
        "limit": limit,
        "offset": offset,
    }


def build_go_rollback_drill_acknowledgement_audit_delivery_worker_health_alert_dashboard(
    items: list[dict[str, Any]],
) -> dict[str, Any]:
    history = filter_go_rollback_drill_acknowledgement_audit_delivery_worker_health_alert_history(
        items,
        limit=500,
    )["items"]
    plans = [
        item
        for item in history
        if item.get("metadata_kind")
        == "go-backend-rollback-drill-acknowledgement-audit-delivery-worker-health-alert-plan"
    ]
    deliveries = [item for item in history if item.get("metadata_kind") == "release-connector-delivery"]
    acknowledgements = [
        item
        for item in history
        if item.get("metadata_kind")
        == "go-backend-rollback-drill-acknowledgement-audit-delivery-worker-health-alert-ack"
    ]
    latest_plan_by_health: dict[str, dict[str, Any]] = {}
    for plan in plans:
        health_id = str(plan.get("health_id") or "")
        if not health_id:
            continue
        current = latest_plan_by_health.get(health_id)
        if current is None or str(plan.get("created_at", "")) > str(current.get("created_at", "")):
            latest_plan_by_health[health_id] = plan
    acknowledged = {
        (str(item.get("health_id")), str(item.get("provider")))
        for item in acknowledgements
        if item.get("acknowledgement_state") in {"acknowledged", "resolved"}
    }
    outstanding = []
    for plan in latest_plan_by_health.values():
        for provider in plan.get("acknowledgement_required_providers", []):
            key = (str(plan.get("health_id")), str(provider))
            if key not in acknowledged:
                outstanding.append({"health_id": key[0], "provider": key[1], "plan_id": plan.get("plan_id")})
    failed_deliveries = [item for item in deliveries if not item.get("delivery_success")]
    suppressed_count = sum(len(item.get("suppressed_providers", [])) for item in plans)
    alert_level = "critical" if failed_deliveries or outstanding else "warning" if suppressed_count else "healthy"
    return {
        "schema_version": "cavra.go-backend-pilot.rollback-drill-acknowledgement-audit-delivery-worker-health-alert-dashboard.v1",
        "product": "CAVRA",
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "alert_level": alert_level,
        "plan_count": len(plans),
        "delivery_count": len(deliveries),
        "failed_delivery_count": len(failed_deliveries),
        "acknowledgement_count": len(acknowledgements),
        "outstanding_acknowledgement_count": len(outstanding),
        "suppressed_provider_count": suppressed_count,
        "outstanding_acknowledgements": outstanding[:20],
        "latest": history[:10],
    }


